package com.project.tuitionmanagementapp.admin

import android.app.AlertDialog
import android.app.TimePickerDialog
import android.content.Context
import android.view.LayoutInflater
import android.widget.*
import com.google.android.material.textfield.TextInputEditText
import com.google.firebase.firestore.FirebaseFirestore
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class ClassScheduleDialog(
    private val context: Context,
    private val selectedDate: Long,
    private val existingSchedule: ClassSchedule? = null,
    private val onSave: (ClassSchedule) -> Unit
) {
    private lateinit var dialog: AlertDialog
    private lateinit var spinnerClass: AutoCompleteTextView
    private lateinit var spinnerTeacher: AutoCompleteTextView
    private lateinit var edtStartTime: TextInputEditText
    private lateinit var edtEndTime: TextInputEditText
    private lateinit var edtRoomNumber: TextInputEditText
    private lateinit var checkboxRecurring: CheckBox
    private lateinit var checkboxNotification: CheckBox

    private var startTime: Long = 0
    private var endTime: Long = 0
    private val firestore = FirebaseFirestore.getInstance()

    fun show() {
        val view = LayoutInflater.from(context).inflate(R.layout.dialog_schedule_class, null)
        initializeViews(view)
        setupTimeSelectors()
        loadTeachersAndClasses()
        loadExistingData()

        dialog = AlertDialog.Builder(context)
            .setView(view)
            .setCancelable(true)
            .create()

        view.findViewById<Button>(R.id.btnSave).setOnClickListener {
            if (validateInputs()) {
                val schedule = createScheduleFromInputs()
                onSave(schedule)
                dialog.dismiss()
            }
        }

        view.findViewById<Button>(R.id.btnCancel).setOnClickListener {
            dialog.dismiss()
        }

        dialog.show()
    }

    private fun initializeViews(view: android.view.View) {
        spinnerClass = view.findViewById(R.id.spinnerClass)
        spinnerTeacher = view.findViewById(R.id.spinnerTeacher)
        edtStartTime = view.findViewById(R.id.edtStartTime)
        edtEndTime = view.findViewById(R.id.edtEndTime)
        edtRoomNumber = view.findViewById(R.id.edtRoomNumber)
        checkboxRecurring = view.findViewById(R.id.checkboxRecurring)
        checkboxNotification = view.findViewById(R.id.checkboxNotification)
    }

    private fun setupTimeSelectors() {
        edtStartTime.setOnClickListener {
            showTimePicker(true)
        }

        edtEndTime.setOnClickListener {
            showTimePicker(false)
        }
    }

    private fun showTimePicker(isStartTime: Boolean) {
        val calendar = Calendar.getInstance()

        TimePickerDialog(
            context,
            { _, hourOfDay, minute ->
                calendar.timeInMillis = selectedDate
                calendar.set(Calendar.HOUR_OF_DAY, hourOfDay)
                calendar.set(Calendar.MINUTE, minute)

                val time = calendar.timeInMillis
                val timeString = SimpleDateFormat("hh:mm a", Locale.getDefault())
                    .format(calendar.time)

                if (isStartTime) {
                    startTime = time
                    edtStartTime.setText(timeString)
                } else {
                    endTime = time
                    edtEndTime.setText(timeString)
                }
            },
            calendar.get(Calendar.HOUR_OF_DAY),
            calendar.get(Calendar.MINUTE),
            false
        ).show()
    }

    private fun loadTeachersAndClasses() {
        // Load teachers
        firestore.collection("teachers")
            .get()
            .addOnSuccessListener { documents ->
                val teachers = documents.mapNotNull { it.getString("name") }
                val teacherAdapter = ArrayAdapter(context, 
                    android.R.layout.simple_dropdown_item_1line, teachers)
                spinnerTeacher.setAdapter(teacherAdapter)
            }

        // Load classes
        firestore.collection("classes")
            .get()
            .addOnSuccessListener { documents ->
                val classes = documents.mapNotNull { it.getString("name") }
                val classAdapter = ArrayAdapter(context, 
                    android.R.layout.simple_dropdown_item_1line, classes)
                spinnerClass.setAdapter(classAdapter)
            }
    }

    private fun loadExistingData() {
        existingSchedule?.let { schedule ->
            spinnerClass.setText(schedule.className)
            spinnerTeacher.setText(schedule.teacherName)
            edtRoomNumber.setText(schedule.roomNumber)
            checkboxRecurring.isChecked = schedule.recurring
            checkboxNotification.isChecked = schedule.notificationEnabled

            // Set times
            startTime = schedule.startTime
            endTime = schedule.endTime
            val sdf = SimpleDateFormat("hh:mm a", Locale.getDefault())
            edtStartTime.setText(sdf.format(Date(startTime)))
            edtEndTime.setText(sdf.format(Date(endTime)))
        }
    }

    private fun validateInputs(): Boolean {
        if (spinnerClass.text.isNullOrBlank()) {
            Toast.makeText(context, "Please select a class", Toast.LENGTH_SHORT).show()
            return false
        }
        if (spinnerTeacher.text.isNullOrBlank()) {
            Toast.makeText(context, "Please select a teacher", Toast.LENGTH_SHORT).show()
            return false
        }
        if (startTime == 0L) {
            Toast.makeText(context, "Please select start time", Toast.LENGTH_SHORT).show()
            return false
        }
        if (endTime == 0L) {
            Toast.makeText(context, "Please select end time", Toast.LENGTH_SHORT).show()
            return false
        }
        if (endTime <= startTime) {
            Toast.makeText(context, "End time must be after start time", Toast.LENGTH_SHORT).show()
            return false
        }
        if (edtRoomNumber.text.isNullOrBlank()) {
            Toast.makeText(context, "Please enter room number", Toast.LENGTH_SHORT).show()
            return false
        }
        return true
    }

    private fun createScheduleFromInputs(): ClassSchedule {
        return ClassSchedule(
            id = existingSchedule?.id,
            className = spinnerClass.text.toString(),
            teacherName = spinnerTeacher.text.toString(),
            startTime = startTime,
            endTime = endTime,
            roomNumber = edtRoomNumber.text.toString(),
            recurring = checkboxRecurring.isChecked,
            notificationEnabled = checkboxNotification.isChecked
        )
    }
}

package com.project.tuitionmanagementapp.admin

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class NotificationHelper(private val context: Context) {

    companion object {
        const val CHANNEL_ID = "class_schedule_channel"
        const val CHANNEL_NAME = "Class Schedule"
        const val CHANNEL_DESCRIPTION = "Notifications for upcoming classes"
    }

    init {
        createNotificationChannel()
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val importance = NotificationManager.IMPORTANCE_HIGH
            val channel = NotificationChannel(CHANNEL_ID, CHANNEL_NAME, importance).apply {
                description = CHANNEL_DESCRIPTION
                enableLights(true)
                lightColor = context.getColor(R.color.purple_700)
                enableVibration(true)
            }

            val notificationManager = context.getSystemService(NotificationManager::class.java)
            notificationManager.createNotificationChannel(channel)
        }
    }

    fun scheduleClassNotification(classSchedule: ClassSchedule) {
        val intent = Intent(context, ClassScheduleActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            classSchedule.hashCode(),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val timeFormat = SimpleDateFormat("hh:mm a", Locale.getDefault())
        val startTime = timeFormat.format(Date(classSchedule.startTime))

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_class)
            .setContentTitle("Upcoming Class: ${classSchedule.className}")
            .setContentText("${classSchedule.teacherName} at $startTime in Room ${classSchedule.roomNumber}")
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setColor(context.getColor(R.color.purple_700))

        with(NotificationManagerCompat.from(context)) {
            notify(classSchedule.hashCode(), builder.build())
        }
    }

    fun scheduleAttendanceReminder(classSchedule: ClassSchedule) {
        val intent = Intent(context, ClassScheduleActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            classSchedule.hashCode() + 1,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_attendance)
            .setContentTitle("Take Attendance")
            .setContentText("Don't forget to take attendance for ${classSchedule.className}")
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setColor(context.getColor(R.color.purple_700))

        with(NotificationManagerCompat.from(context)) {
            notify(classSchedule.hashCode() + 1, builder.build())
        }
    }
}

package com.project.tuitionmanagementapp.admin

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageButton
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class ScheduleAdapter(
    private val schedules: List<ClassSchedule>,
    private val onEdit: (ClassSchedule) -> Unit,
    private val onDelete: (ClassSchedule) -> Unit,
    private val onAttendance: (ClassSchedule) -> Unit
) : RecyclerView.Adapter<ScheduleAdapter.ScheduleViewHolder>() {

    inner class ScheduleViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cardView: CardView = itemView.findViewById(R.id.cardSchedule)
        val className: TextView = itemView.findViewById(R.id.tvClassName)
        val teacherName: TextView = itemView.findViewById(R.id.tvTeacherName)
        val timeSlot: TextView = itemView.findViewById(R.id.tvTimeSlot)
        val roomNumber: TextView = itemView.findViewById(R.id.tvRoomNumber)
        val btnEdit: ImageButton = itemView.findViewById(R.id.btnEdit)
        val btnDelete: ImageButton = itemView.findViewById(R.id.btnDelete)
        val btnAttendance: ImageButton = itemView.findViewById(R.id.btnAttendance)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ScheduleViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_schedule, parent, false)
        return ScheduleViewHolder(view)
    }

    override fun onBindViewHolder(holder: ScheduleViewHolder, position: Int) {
        val schedule = schedules[position]

        holder.className.text = schedule.className
        holder.teacherName.text = schedule.teacherName
        holder.timeSlot.text = formatTimeSlot(schedule.startTime, schedule.endTime)
        holder.roomNumber.text = "Room ${schedule.roomNumber}"

        // Set recurring indicator if applicable
        if (schedule.recurring) {
            holder.timeSlot.setCompoundDrawablesWithIntrinsicBounds(
                R.drawable.ic_recurring, 0, 0, 0)
        }

        // Action buttons
        holder.btnEdit.setOnClickListener { onEdit(schedule) }
        holder.btnDelete.setOnClickListener { onDelete(schedule) }
        holder.btnAttendance.setOnClickListener { onAttendance(schedule) }

        // Visual indication for past classes
        val now = System.currentTimeMillis()
        if (schedule.endTime < now) {
            holder.cardView.alpha = 0.7f
        } else {
            holder.cardView.alpha = 1.0f
        }
    }

    override fun getItemCount() = schedules.size

    private fun formatTimeSlot(startTime: Long, endTime: Long): String {
        val sdf = SimpleDateFormat("hh:mm a", Locale.getDefault())
        return "${sdf.format(Date(startTime))} - ${sdf.format(Date(endTime))}"
    }
}

