        }
        btnSaveProfile.setOnClickListener {
            saveProfileChanges()
        }
        imgStudentProfile.setOnClickListener {
            if (isEditing) pickProfileImage()
        }
            // Navigate to login screen or perform other actions
        btnLogout.setOnClickListener {
            auth.signOut()
            // Navigate to login screen or perform other actions
        }
        enableEditing(false)
    }

