package com.project.tuitionmanagementapp.teacher

import android.app.*
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.appcompat.widget.Toolbar
import com.google.firebase.database.FirebaseDatabase
import com.google.firebase.storage.FirebaseStorage
import com.project.tuitionmanagementapp.R
import java.util.*

class AssignmentActivity : AppCompatActivity() {

    private lateinit var etTitle: EditText
    private lateinit var spinnerGrade: Spinner
    private lateinit var etSubmissionDate: EditText
    private lateinit var etSubmissionTime: EditText
    private lateinit var btnChooseFile: Button
    private lateinit var tvFileName: TextView
    private lateinit var btnUpload: Button

    private var selectedFileUri: Uri? = null
    private val PICK_PDF_REQUEST = 1001
    private var selectedDate = ""
    private var selectedTime = ""

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_assignment)

        //  Toolbar setup
        val toolbar = findViewById<Toolbar>(R.id.toolbar)
        setSupportActionBar(toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        supportActionBar?.title = "Upload Assignment"

        // View bindings
        etTitle = findViewById(R.id.etAssignmentTitle)
        spinnerGrade = findViewById(R.id.spinnerGrade)
        etSubmissionDate = findViewById(R.id.etSubmissionDate)
        etSubmissionTime = findViewById(R.id.etSubmissionTime)
        btnChooseFile = findViewById(R.id.btnChooseFile)
        tvFileName = findViewById(R.id.tvFileName)
        btnUpload = findViewById(R.id.btnUploadAssignment)

        //  Spinner data
        val grades = listOf("Select Grade", "Grade 6", "Grade 7", "Grade 8", "Grade 9", "Grade 10")
        spinnerGrade.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, grades)

        //  Date picker
        etSubmissionDate.setOnClickListener {
            val calendar = Calendar.getInstance()
            DatePickerDialog(this, { _, y, m, d ->
                selectedDate = String.format("%02d-%02d-%04d", d, m + 1, y)
                etSubmissionDate.setText(selectedDate)
            }, calendar.get(Calendar.YEAR), calendar.get(Calendar.MONTH), calendar.get(Calendar.DAY_OF_MONTH)).show()
        }

        // ⏰ Time picker
        etSubmissionTime.setOnClickListener {
            val calendar = Calendar.getInstance()
            TimePickerDialog(this, { _, h, min ->
                selectedTime = String.format("%02d:%02d", h, min)
                etSubmissionTime.setText(selectedTime)
            }, calendar.get(Calendar.HOUR_OF_DAY), calendar.get(Calendar.MINUTE), true).show()
        }

        //  Choose PDF
        btnChooseFile.setOnClickListener {
            val intent = Intent(Intent.ACTION_GET_CONTENT)
            intent.type = "application/pdf"
            startActivityForResult(Intent.createChooser(intent, "Select PDF"), PICK_PDF_REQUEST)
        }

        // ⬆️ Upload
        btnUpload.setOnClickListener {
            uploadAssignment()
        }
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (resultCode == Activity.RESULT_OK && data != null) {
            selectedFileUri = data.data
            tvFileName.text = selectedFileUri?.lastPathSegment ?: "File selected"
        }
    }

    private fun uploadAssignment() {
        val title = etTitle.text.toString().trim()
        val grade = spinnerGrade.selectedItem.toString()

        if (title.isEmpty() || selectedDate.isEmpty() || selectedTime.isEmpty() || grade == "Select Grade" || selectedFileUri == null) {
            Toast.makeText(this, "Please complete all fields and select a file", Toast.LENGTH_SHORT).show()
            return
        }

        // Show loading
        val progressDialog = ProgressDialog(this)
        progressDialog.setMessage("Uploading assignment...")
        progressDialog.setCancelable(false)
        progressDialog.show()

        // Create unique filename
        val timestamp = System.currentTimeMillis()
        val filename = "assignment_${timestamp}.pdf"

        // Firebase storage reference
        val storageRef = FirebaseStorage.getInstance().reference
            .child("assignments")
            .child(filename)

        // Upload file
        storageRef.putFile(selectedFileUri!!)
            .addOnSuccessListener {
                // Get download URL
                storageRef.downloadUrl.addOnSuccessListener { uri ->
                    // Create assignment object
                    val assignmentMap = HashMap<String, Any>()
                    assignmentMap["title"] = title
                    assignmentMap["grade"] = grade
                    assignmentMap["submissionDate"] = selectedDate
                    assignmentMap["submissionTime"] = selectedTime
                    assignmentMap["fileUrl"] = uri.toString()
                    assignmentMap["timestamp"] = timestamp

                    // Save to database
                    FirebaseDatabase.getInstance().reference
                        .child("assignments")
                        .push()
                        .setValue(assignmentMap)
                        .addOnCompleteListener { task ->
                            progressDialog.dismiss()
                            if (task.isSuccessful) {
                                Toast.makeText(this, "Assignment uploaded successfully", Toast.LENGTH_SHORT).show()
                                finish()
                            } else {
                                Toast.makeText(this, "Failed to upload assignment: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                            }
                        }
                }
            }
            .addOnFailureListener { e ->
                progressDialog.dismiss()
                Toast.makeText(this, "Upload failed: ${e.message}", Toast.LENGTH_SHORT).show()
            }
            .addOnProgressListener { taskSnapshot ->
                val progress = (100.0 * taskSnapshot.bytesTransferred / taskSnapshot.totalByteCount)
                progressDialog.setMessage("Uploading: ${progress.toInt()}%")
            }
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.project.tuitionmanagementapp.teacher

import android.app.*
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.appcompat.widget.Toolbar
import com.google.firebase.database.FirebaseDatabase
import com.google.firebase.storage.FirebaseStorage
import com.project.tuitionmanagementapp.R
import java.util.*

class AssignmentActivity : AppCompatActivity() {

    private lateinit var etTitle: EditText
    private lateinit var spinnerGrade: Spinner
    private lateinit var etSubmissionDate: EditText
    private lateinit var etSubmissionTime: EditText
    private lateinit var btnChooseFile: Button
    private lateinit var tvFileName: TextView
    private lateinit var btnUpload: Button

    private var selectedFileUri: Uri? = null
    private val PICK_PDF_REQUEST = 1001
    private var selectedDate = ""
    private var selectedTime = ""

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_assignment)

        // Toolbar setup
        val toolbar = findViewById<Toolbar>(R.id.toolbar)
        setSupportActionBar(toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        supportActionBar?.title = "Upload Assignment"

        // View bindings
        etTitle = findViewById(R.id.etAssignmentTitle)
        spinnerGrade = findViewById(R.id.spinnerGrade)
        etSubmissionDate = findViewById(R.id.etSubmissionDate)
        etSubmissionTime = findViewById(R.id.etSubmissionTime)
        btnChooseFile = findViewById(R.id.btnChooseFile)
        tvFileName = findViewById(R.id.tvFileName)
        btnUpload = findViewById(R.id.btnUploadAssignment)

        // Spinner data
        val grades = listOf("Select Grade", "Grade 6", "Grade 7", "Grade 8", "Grade 9", "Grade 10")
        spinnerGrade.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, grades)

        // Date picker
        etSubmissionDate.setOnClickListener {
            val calendar = Calendar.getInstance()
            DatePickerDialog(this, { _, y, m, d ->
                selectedDate = String.format("%02d-%02d-%04d", d, m + 1, y)
                etSubmissionDate.setText(selectedDate)
            }, calendar.get(Calendar.YEAR), calendar.get(Calendar.MONTH), calendar.get(Calendar.DAY_OF_MONTH)).show()
        }

        // Time picker
        etSubmissionTime.setOnClickListener {
            val calendar = Calendar.getInstance()
            TimePickerDialog(this, { _, h, min ->
                selectedTime = String.format("%02d:%02d", h, min)
                etSubmissionTime.setText(selectedTime)
            }, calendar.get(Calendar.HOUR_OF_DAY), calendar.get(Calendar.MINUTE), true).show()
        }

        // Choose PDF
        btnChooseFile.setOnClickListener {
            val intent = Intent(Intent.ACTION_GET_CONTENT)
            intent.type = "application/pdf"
            startActivityForResult(Intent.createChooser(intent, "Select PDF"), PICK_PDF_REQUEST)
        }

        // Upload
        btnUpload.setOnClickListener {
            uploadAssignment()
        }
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == PICK_PDF_REQUEST && resultCode == Activity.RESULT_OK && data != null) {
            selectedFileUri = data.data
            tvFileName.text = selectedFileUri?.lastPathSegment ?: "File selected"
        }
    }

    private fun uploadAssignment() {
        val title = etTitle.text.toString().trim()
        val grade = spinnerGrade.selectedItem.toString()

        if (title.isEmpty() || selectedDate.isEmpty() || selectedTime.isEmpty() || grade == "Select Grade" || selectedFileUri == null) {
            Toast.makeText(this, "Please complete all fields and select a file", Toast.LENGTH_SHORT).show()
            return
        }

        // Show loading
        val progressDialog = ProgressDialog(this)
        progressDialog.setMessage("Uploading assignment...")
        progressDialog.setCancelable(false)
        progressDialog.show()

        // Create unique filename
        val timestamp = System.currentTimeMillis()
        val filename = "assignment_${timestamp}.pdf"

        // Firebase storage reference
        val storageRef = FirebaseStorage.getInstance().reference
            .child("assignments")
            .child(filename)

        // Upload file
        storageRef.putFile(selectedFileUri!!)
            .addOnSuccessListener {
                // Get download URL
                storageRef.downloadUrl.addOnSuccessListener { uri ->
                    // Create assignment object
                    val assignmentMap = HashMap<String, Any>()
                    assignmentMap["title"] = title
                    assignmentMap["grade"] = grade
                    assignmentMap["submissionDate"] = selectedDate
                    assignmentMap["submissionTime"] = selectedTime
                    assignmentMap["fileUrl"] = uri.toString()
                    assignmentMap["timestamp"] = timestamp

                    // Save to database
                    FirebaseDatabase.getInstance().reference
                        .child("assignments")
                        .push()
                        .setValue(assignmentMap)
                        .addOnCompleteListener { task ->
                            progressDialog.dismiss()
                            if (task.isSuccessful) {
                                Toast.makeText(this, "Assignment uploaded successfully", Toast.LENGTH_SHORT).show()
                                finish()
                            } else {
                                Toast.makeText(this, "Failed to upload assignment: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                            }
                        }
                }
            }
            .addOnFailureListener { e ->
                progressDialog.dismiss()
                Toast.makeText(this, "Upload failed: ${e.message}", Toast.LENGTH_SHORT).show()
            }
            .addOnProgressListener { taskSnapshot ->
                val progress = (100.0 * taskSnapshot.bytesTransferred / taskSnapshot.totalByteCount)
                progressDialog.setMessage("Uploading: ${progress.toInt()}%")
            }
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.project.tuitionmanagementapp.teacher

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageButton
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class AssignmentAdapter(
    private val assignments: List<Assignment>,
    private val onViewSubmissions: (Assignment) -> Unit,
    private val onEdit: (Assignment) -> Unit,
    private val onDelete: (Assignment) -> Unit
) : RecyclerView.Adapter<AssignmentAdapter.AssignmentViewHolder>() {

    inner class AssignmentViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cardView: CardView = itemView.findViewById(R.id.cardAssignment)
        val title: TextView = itemView.findViewById(R.id.tvAssignmentTitle)
        val description: TextView = itemView.findViewById(R.id.tvAssignmentDescription)
        val dueDate: TextView = itemView.findViewById(R.id.tvDueDate)
        val className: TextView = itemView.findViewById(R.id.tvClassName)
        val btnSubmissions: ImageButton = itemView.findViewById(R.id.btnViewSubmissions)
        val btnEdit: ImageButton = itemView.findViewById(R.id.btnEdit)
        val btnDelete: ImageButton = itemView.findViewById(R.id.btnDelete)
        val status: TextView = itemView.findViewById(R.id.tvStatus)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): AssignmentViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_assignment_teacher, parent, false)
        return AssignmentViewHolder(view)
    }

    override fun onBindViewHolder(holder: AssignmentViewHolder, position: Int) {
        val assignment = assignments[position]

        holder.title.text = assignment.title
        holder.description.text = assignment.description
        holder.dueDate.text = formatDate(assignment.dueDate)
        holder.className.text = assignment.className

        // Set status color based on due date
        val now = System.currentTimeMillis()
        val statusColor = when {
            assignment.status == "completed" -> holder.itemView.context.getColor(R.color.green)
            now > assignment.dueDate -> holder.itemView.context.getColor(R.color.red)
            else -> holder.itemView.context.getColor(R.color.purple_700)
        }
        holder.status.setTextColor(statusColor)

        // Set status text
        holder.status.text = when {
            assignment.status == "completed" -> "Completed"
            now > assignment.dueDate -> "Expired"
            else -> "Active"
        }

        // Setup click listeners
        holder.btnSubmissions.setOnClickListener { onViewSubmissions(assignment) }
        holder.btnEdit.setOnClickListener { onEdit(assignment) }
        holder.btnDelete.setOnClickListener { onDelete(assignment) }
    }

    override fun getItemCount() = assignments.size

    private fun formatDate(timestamp: Long): String {
        val sdf = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        return sdf.format(Date(timestamp))
    }
}

package com.project.tuitionmanagementapp.teacher

import android.app.AlertDialog
import android.app.DatePickerDialog
import android.content.Context
import android.view.LayoutInflater
import android.widget.ArrayAdapter
import android.widget.AutoCompleteTextView
import android.widget.Button
import android.widget.EditText
import com.google.android.material.textfield.TextInputEditText
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class AssignmentDialog(
    private val context: Context,
    private val existingAssignment: Assignment? = null,
    private val onSave: (Assignment) -> Unit
) {
    private lateinit var dialog: AlertDialog
    private lateinit var titleInput: TextInputEditText
    private lateinit var descriptionInput: TextInputEditText
    private lateinit var dueDateInput: TextInputEditText
    private lateinit var classSpinner: AutoCompleteTextView
    private var selectedDueDate: Long = 0

    fun show() {
        val view = LayoutInflater.from(context).inflate(R.layout.dialog_create_assignment, null)
        initializeViews(view)
        setupDatePicker()
        setupClassSpinner()
        loadExistingAssignment()

        dialog = AlertDialog.Builder(context)
            .setView(view)
            .setCancelable(true)
            .create()

        // Handle save button click
        view.findViewById<Button>(R.id.btnSave).setOnClickListener {
            if (validateInputs()) {
                val assignment = createAssignmentFromInputs()
                onSave(assignment)
                dialog.dismiss()
            }
        }

        // Handle cancel button click
        view.findViewById<Button>(R.id.btnCancel).setOnClickListener {
            dialog.dismiss()
        }

        dialog.show()
    }

    private fun initializeViews(view: android.view.View) {
        titleInput = view.findViewById(R.id.edtAssignmentTitle)
        descriptionInput = view.findViewById(R.id.edtAssignmentDescription)
        dueDateInput = view.findViewById(R.id.edtDueDate)
        classSpinner = view.findViewById(R.id.spinnerClass)
    }

    private fun setupDatePicker() {
        dueDateInput.setOnClickListener {
            val calendar = Calendar.getInstance()

            DatePickerDialog(
                context,
                { _, year, month, day ->
                    calendar.set(year, month, day)
                    selectedDueDate = calendar.timeInMillis
                    dueDateInput.setText(formatDate(selectedDueDate))
                },
                calendar.get(Calendar.YEAR),
                calendar.get(Calendar.MONTH),
                calendar.get(Calendar.DAY_OF_MONTH)
            ).show()
        }
    }

    private fun setupClassSpinner() {
        // Sample class list - Replace with actual class list from your database
        val classes = listOf("Class A", "Class B", "Class C")
        val adapter = ArrayAdapter(context, android.R.layout.simple_dropdown_item_1line, classes)
        classSpinner.setAdapter(adapter)
    }

    private fun loadExistingAssignment() {
        existingAssignment?.let { assignment ->
            titleInput.setText(assignment.title)
            descriptionInput.setText(assignment.description)
            dueDateInput.setText(formatDate(assignment.dueDate))
            selectedDueDate = assignment.dueDate
            classSpinner.setText(assignment.className, false)
        }
    }

    private fun validateInputs(): Boolean {
        var isValid = true

        if (titleInput.text.isNullOrBlank()) {
            titleInput.error = "Title is required"
            isValid = false
        }

        if (descriptionInput.text.isNullOrBlank()) {
            descriptionInput.error = "Description is required"
            isValid = false
        }

        if (selectedDueDate == 0L) {
            dueDateInput.error = "Due date is required"
            isValid = false
        }

        if (classSpinner.text.isNullOrBlank()) {
            classSpinner.error = "Class is required"
            isValid = false
        }

        return isValid
    }

    private fun createAssignmentFromInputs(): Assignment {
        return Assignment(
            id = existingAssignment?.id,
            title = titleInput.text.toString(),
            description = descriptionInput.text.toString(),
            dueDate = selectedDueDate,
            className = classSpinner.text.toString(),
            attachmentUrl = existingAssignment?.attachmentUrl,
            teacherId = existingAssignment?.teacherId ?: "", // Set actual teacher ID
            createdAt = existingAssignment?.createdAt ?: System.currentTimeMillis(),
            status = existingAssignment?.status ?: "active"
        )
    }

    private fun formatDate(timestamp: Long): String {
        val sdf = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        return sdf.format(Date(timestamp))
    }
}

