package com.project.tuitionmanagementapp.teacher

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageView
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class MaterialsAdapter(
    private val materials: List<MaterialModel>,
    private val onItemClick: (MaterialModel) -> Unit
) : RecyclerView.Adapter<MaterialsAdapter.MaterialViewHolder>() {

    inner class MaterialViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cardView: CardView = itemView.findViewById(R.id.cardMaterial)
        val title: TextView = itemView.findViewById(R.id.tvMaterialTitle)
        val type: TextView = itemView.findViewById(R.id.tvMaterialType)
        val date: TextView = itemView.findViewById(R.id.tvUploadDate)
        val icon: ImageView = itemView.findViewById(R.id.imgMaterialIcon)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): MaterialViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_material, parent, false)
        return MaterialViewHolder(view)
    }

    override fun onBindViewHolder(holder: MaterialViewHolder, position: Int) {
        val material = materials[position]

        holder.title.text = material.title
        holder.type.text = material.type
        holder.date.text = formatDate(material.uploadDate)

        // Set icon based on material type
        holder.icon.setImageResource(
            when (material.type.lowercase()) {
                "pdf" -> R.drawable.ic_pdf
                "video" -> R.drawable.ic_video
                else -> R.drawable.ic_document
            }
        )

        // Set card click listener
        holder.cardView.setOnClickListener { onItemClick(material) }

        // Apply theme colors
        holder.icon.setColorFilter(holder.itemView.context.getColor(R.color.purple_700))
    }

    override fun getItemCount() = materials.size

    private fun formatDate(timestamp: Long): String {
        val sdf = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        return sdf.format(Date(timestamp))
    }
}

package com.project.tuitionmanagementapp.teacher

import android.content.Intent
import android.os.Bundle
import android.widget.ImageView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.*
import com.google.firebase.firestore.FirebaseFirestore
import com.google.zxing.integration.android.IntentIntegrator
import com.google.zxing.integration.android.IntentResult
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class QRAttendanceActivity : AppCompatActivity() {

    private lateinit var btnBack: ImageView
    private lateinit var recyclerAttendance: RecyclerView
    private lateinit var auth: FirebaseAuth
    private lateinit var firestore: FirebaseFirestore
    private lateinit var database: FirebaseDatabase

    private val attendanceList = mutableListOf<AttendanceRecord>()
    private lateinit var attendanceAdapter: AttendanceAdapter

    data class AttendanceRecord(
        val studentId: String = "",
        val studentName: String = "",
        val timestamp: String = "",
        val status: String = "Present"
    )

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_qr_scanner)

        // Initialize Firebase
        auth = FirebaseAuth.getInstance()
        firestore = FirebaseFirestore.getInstance()
        database = FirebaseDatabase.getInstance()

        initViews()
        setupRecyclerView()
        setupClickListeners()

        // Start scanner automatically
        startQRScanner()
    }

    private fun initViews() {
        btnBack = findViewById(R.id.btnBack)

        // Add RecyclerView to scan results
        // Note: This is not in the current layout, but we'll handle it gracefully
        recyclerAttendance = findViewById<RecyclerView>(R.id.recyclerAttendance)?.apply {
            layoutManager = LinearLayoutManager(this@QRAttendanceActivity)
        } ?: RecyclerView(this).apply {
            layoutManager = LinearLayoutManager(this@QRAttendanceActivity)
        }

        // Setup toolbar
        supportActionBar?.title = "QR Attendance Scanner"
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
    }

    private fun setupRecyclerView() {
        attendanceAdapter = AttendanceAdapter(attendanceList)
        recyclerAttendance.adapter = attendanceAdapter
    }

    private fun setupClickListeners() {
        btnBack.setOnClickListener {
            finish()
        }
    }

    private fun startQRScanner() {
        val integrator = IntentIntegrator(this)
        integrator.setPrompt("Scan Student QR Code for Attendance")
        integrator.setBeepEnabled(true)
        integrator.setOrientationLocked(true)
        integrator.captureActivity = CaptureActivityPortrait::class.java
        integrator.initiateScan()
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        val result: IntentResult? = IntentIntegrator.parseActivityResult(requestCode, resultCode, data)

        if (result != null) {
            if (result.contents == null) {
                Toast.makeText(this, "Scan cancelled", Toast.LENGTH_SHORT).show()
            } else {
                val studentId = result.contents.trim()
                processScannedStudentId(studentId)
            }
        } else {
            super.onActivityResult(requestCode, resultCode, data)
        }
    }

    private fun processScannedStudentId(studentId: String) {
        // Check if student already marked present today
        if (isStudentAlreadyMarked(studentId)) {
            Toast.makeText(this, "Student already marked present today", Toast.LENGTH_SHORT).show()
            return
        }

        // Fetch student details
        firestore.collection("students")
            .document(studentId)
            .get()
            .addOnSuccessListener { document ->
                if (document.exists()) {
                    val studentName = document.getString("name") ?: "Unknown Student"
                    markAttendance(studentId, studentName)
                } else {
                    Toast.makeText(this, "Student not found", Toast.LENGTH_SHORT).show()
                }
            }
            .addOnFailureListener {
                Toast.makeText(this, "Failed to fetch student details", Toast.LENGTH_SHORT).show()
            }
    }

    private fun isStudentAlreadyMarked(studentId: String): Boolean {
        return attendanceList.any { it.studentId == studentId }
    }

    private fun markAttendance(studentId: String, studentName: String) {
        val timestamp = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date())

        val attendanceRecord = AttendanceRecord(
            studentId = studentId,
            studentName = studentName,
            timestamp = timestamp
        )

        // Add to local list
        attendanceList.add(attendanceRecord)
        attendanceAdapter.notifyDataSetChanged()

        // Save to Firebase
        val attendanceMap = HashMap<String, Any>()
        attendanceMap["studentId"] = studentId
        attendanceMap["studentName"] = studentName
        attendanceMap["timestamp"] = timestamp
        attendanceMap["status"] = "Present"

        firestore.collection("attendance")
            .add(attendanceMap)
            .addOnSuccessListener {
                Toast.makeText(this, "Attendance marked: $studentName", Toast.LENGTH_SHORT).show()
                // Start scanner again for the next student
                startQRScanner()
            }
            .addOnFailureListener {
                Toast.makeText(this, "Failed to mark attendance", Toast.LENGTH_SHORT).show()
            }
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.project.tuitionmanagementapp.teacher

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageButton
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.recyclerview.widget.RecyclerView
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class ResultAdapter(
    private val results: List<ResultModel>,
    private val onEdit: (ResultModel) -> Unit
) : RecyclerView.Adapter<ResultAdapter.ResultViewHolder>() {

    inner class ResultViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val cardView: CardView = itemView.findViewById(R.id.cardResult)
        val studentName: TextView = itemView.findViewById(R.id.tvStudentName)
        val subject: TextView = itemView.findViewById(R.id.tvSubject)
        val marks: TextView = itemView.findViewById(R.id.tvMarks)
        val grade: TextView = itemView.findViewById(R.id.tvGrade)
        val date: TextView = itemView.findViewById(R.id.tvDate)
        val btnEdit: ImageButton = itemView.findViewById(R.id.btnEdit)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ResultViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_result_teacher, parent, false)
        return ResultViewHolder(view)
    }

    override fun onBindViewHolder(holder: ResultViewHolder, position: Int) {
        val result = results[position]

        holder.studentName.text = result.studentName
        holder.subject.text = result.subject
        holder.marks.text = "${result.marks}/${result.totalMarks}"
        holder.grade.text = result.grade
        holder.date.text = formatDate(result.examDate)

        // Set grade color based on result
        val gradeColor = when {
            result.marks >= (result.totalMarks * 0.8) -> holder.itemView.context.getColor(R.color.green)
            result.marks >= (result.totalMarks * 0.4) -> holder.itemView.context.getColor(R.color.purple_700)
            else -> holder.itemView.context.getColor(R.color.red)
        }
        holder.grade.setTextColor(gradeColor)

        // Edit button click
        holder.btnEdit.setOnClickListener { onEdit(result) }
    }

    override fun getItemCount() = results.size

    private fun formatDate(timestamp: Long): String {
        val sdf = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        return sdf.format(Date(timestamp))
    }
}

package com.project.tuitionmanagementapp.teacher

data class ResultModel(
    val id: String? = null,
    val studentId: String = "",
    val studentName: String = "",
    val subject: String = "",
    val marks: Int = 0,
    val totalMarks: Int = 100,
    val grade: String = "",
    val examDate: Long = System.currentTimeMillis(),
    val teacherId: String = "",
    val comment: String = "",
    val className: String = ""
) {
    fun calculateGrade(): String {
        val percentage = (marks.toFloat() / totalMarks) * 100
        return when {
            percentage >= 90 -> "A+"
            percentage >= 80 -> "A"
            percentage >= 70 -> "B+"
            percentage >= 60 -> "B"
            percentage >= 50 -> "C"
            percentage >= 40 -> "D"
            else -> "F"
        }
    }

    fun getPercentage(): Float {
        return (marks.toFloat() / totalMarks) * 100
    }

    fun getStatus(): String {
        return if (marks >= (totalMarks * 0.4)) "Pass" else "Fail"
    }
}

package com.project.tuitionmanagementapp.teacher

import android.content.Intent
import android.content.SharedPreferences
import android.os.Bundle
import android.view.View
import android.widget.ImageView
import android.widget.PopupMenu
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.cardview.widget.CardView
import com.google.android.material.bottomnavigation.BottomNavigationView
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.project.tuitionmanagementapp.R
import com.project.tuitionmanagementapp.auth.LoginActivity
import java.text.SimpleDateFormat
import java.util.*

class TeacherDashboardActivity : AppCompatActivity() {

    private lateinit var auth: FirebaseAuth
    private lateinit var firestore: FirebaseFirestore
    private lateinit var sharedPreferences: SharedPreferences

    private lateinit var imgProfile: ImageView
    private lateinit var imgOptions: ImageView
    private lateinit var tvTeacherName: TextView
    private lateinit var bottomNavigationView: BottomNavigationView

    private var currentTeacherId: String? = null
    private var currentTeacherName: String? = null
    private var currentTeacherEmail: String? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_teacher_dashboard)

        // Initialize Firebase
        auth = FirebaseAuth.getInstance()
        firestore = FirebaseFirestore.getInstance()
        sharedPreferences = getSharedPreferences("TeacherPrefs", MODE_PRIVATE)

        initViews()
        loadTeacherData()
        setupNavigation()
        setupClickListeners()
    }

    private fun initViews() {
        imgProfile = findViewById(R.id.imgProfile)
        imgOptions = findViewById(R.id.imgOptions)
        tvTeacherName = findViewById(R.id.tvTeacherName)

        // Find CardViews for each action
        // Using findViewById with null-safe calls and finding parent CardView instead of LinearLayout
        val attendanceCard = findViewById<CardView>(R.id.attendanceCard)
        val materialsCard = findViewById<CardView>(R.id.materialsCard)
        val assignmentsCard = findViewById<CardView>(R.id.assignmentsCard)
        val resultsCard = findViewById<CardView>(R.id.resultsCard)

        // Set click listeners with null checks
        attendanceCard?.setOnClickListener { navigateToAttendance() }
        materialsCard?.setOnClickListener { navigateToMaterials() }
        assignmentsCard?.setOnClickListener { navigateToAssignments() }
        resultsCard?.setOnClickListener { navigateToResults() }

        // Try to find the bottom navigation if it exists
        bottomNavigationView = findViewById(R.id.bottomNavigation)
    }

    private fun loadTeacherData() {
        val currentUser = auth.currentUser
        if (currentUser != null) {
            currentTeacherId = currentUser.uid
            currentTeacherEmail = currentUser.email

            firestore.collection("teachers").document(currentUser.uid)
                .get()
                .addOnSuccessListener { document ->
                    if (document.exists()) {
                        currentTeacherName = document.getString("name") ?: "Teacher"
                        updateUI()

                        // Store in SharedPreferences
                        with(sharedPreferences.edit()) {
                            putString("teacher_id", currentTeacherId)
                            putString("teacher_name", currentTeacherName)
                            putString("teacher_email", currentTeacherEmail)
                            apply()
                        }
                    }
                }
                .addOnFailureListener {
                    Toast.makeText(this, "Failed to load teacher data", Toast.LENGTH_SHORT).show()
                }
        }
    }

    private fun updateUI() {
        // Update teacher name
        tvTeacherName.text = currentTeacherName ?: "Teacher"

        // Note: welcomeText is used instead of tvGreeting
        val welcomeText = findViewById<TextView>(R.id.welcomeText)

        // Update greeting based on time of day
        val calendar = Calendar.getInstance()
        val hour = calendar.get(Calendar.HOUR_OF_DAY)
        val greeting = when {
            hour < 12 -> "Good Morning,"
            hour < 17 -> "Good Afternoon,"
            else -> "Good Evening,"
        }

        welcomeText?.text = greeting
    }

    private fun setupNavigation() {
        bottomNavigationView.selectedItemId = R.id.nav_home
        bottomNavigationView.setOnItemSelectedListener { item ->
            when (item.itemId) {
                R.id.nav_home -> true
                R.id.nav_assignment -> {
                    navigateToAssignments()
                    true
                }
                R.id.nav_materials -> {
                    navigateToMaterials()
                    true
                }
                R.id.nav_profile -> {
                    navigateToProfile()
                    true
                }
                else -> false
            }
        }
    }

    private fun setupClickListeners() {
        imgProfile.setOnClickListener { showProfileMenu(it) }
        imgOptions.setOnClickListener { showOptionsMenu(it) }
    }

    private fun showProfileMenu(view: View) {
        val popup = PopupMenu(this, view)
        popup.menuInflater.inflate(R.menu.teacher_profile_menu, popup.menu)
        popup.setOnMenuItemClickListener { item ->
            when (item.itemId) {
                R.id.menu_edit_profile -> {
                    startActivity(Intent(this, EditProfileActivity::class.java))
                    true
                }
                R.id.menu_settings -> {
                    Toast.makeText(this, "Settings coming soon", Toast.LENGTH_SHORT).show()
                    true
                }
                R.id.menu_logout -> {
                    logoutTeacher()
                    true
                }
                else -> false
            }
        }
        popup.show()
    }

    private fun showOptionsMenu(view: View) {
        val popup = PopupMenu(this, view)
        popup.menuInflater.inflate(R.menu.teacher_options_menu, popup.menu)
        popup.setOnMenuItemClickListener { item ->
            when (item.itemId) {
                R.id.menu_notifications -> {
                    Toast.makeText(this, "Notifications", Toast.LENGTH_SHORT).show()
                    true
                }
                R.id.menu_help -> {
                    Toast.makeText(this, "Help & Support", Toast.LENGTH_SHORT).show()
                    true
                }
                R.id.menu_about -> {
                    Toast.makeText(this, "About Academix", Toast.LENGTH_SHORT).show()
                    true
                }
                else -> false
            }
        }
        popup.show()
    }

    private fun navigateToAttendance() {
        // Show options for attendance - QR Scanner or Manual Entry
        val options = arrayOf("QR Code Scanner", "Manual Attendance", "View Attendance Records")
        android.app.AlertDialog.Builder(this)
            .setTitle("Attendance Options")
            .setItems(options) { _, which ->
                when (which) {
                    0 -> startActivity(Intent(this, QRAttendanceActivity::class.java))
                    1 -> startActivity(Intent(this, AttendanceActivity::class.java))
                    2 -> startActivity(Intent(this, AttendanceActivity::class.java))
                }
            }
            .show()
    }

    private fun navigateToAssignments() = startActivity(Intent(this, AssignmentActivity::class.java))
    private fun navigateToMaterials() = startActivity(Intent(this, TeacherMaterialsActivity::class.java))
    private fun navigateToResults() = startActivity(Intent(this, UploadResultActivity::class.java))
    private fun navigateToAnalytics() = startActivity(Intent(this, AnalyticsActivity::class.java))
    private fun navigateToCalendar() = startActivity(Intent(this, CalendarActivity::class.java))
    private fun navigateToProfile() = startActivity(Intent(this, EditProfileActivity::class.java))

    private fun logoutTeacher() {
        android.app.AlertDialog.Builder(this)
            .setTitle("Logout")
            .setMessage("Are you sure you want to logout?")
            .setPositiveButton("Yes") { _, _ ->
                sharedPreferences.edit().clear().apply()
                auth.signOut()
                startActivity(Intent(this, LoginActivity::class.java).apply {
                    flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                })
                finish()
            }
            .setNegativeButton("No", null)
            .show()
    }

    override fun onResume() {
        super.onResume()
        loadTeacherData()
    }
}

